"""Integration client identity and authentication.

An integration client is a vendor link (one PMS interface), not a human. It
authenticates with a client code plus a generated secret.

Secret handling:
* Secrets are GENERATED by `generate_secret()` (256 bits from `secrets`), never
  chosen by a person, so a fast keyed hash is appropriate (the same reasoning
  as API-token stores): we store `sha256$<hex>` of the secret, compare with
  `hmac.compare_digest`, and never store or log the secret itself.
* Secrets shorter than MIN_SECRET_LENGTH are refused before hashing.
* Unknown client codes are compared against a dummy digest so the time taken
  does not reveal whether the code exists.
* Every failure raises the SAME `AuthenticationFailed`; the internal reason is
  kept on the exception for audit/metrics only.

There is no development bypass. A missing store, a missing credential or a
disabled client always fails closed.
Credential storage location is decision HF-22 (pending).
"""

from __future__ import annotations

import hashlib
import hmac
import re
import secrets
import threading
import uuid
from collections.abc import Callable
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Protocol as TypingProtocol

from app.integrations.core.envelope import Protocol
from app.integrations.core.errors import AuthenticationFailed

MIN_SECRET_LENGTH = 32
MAX_SECRET_LENGTH = 512
HASH_SCHEME = "sha256"
CLIENT_CODE_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.\-]{1,63}$")
_DUMMY_DIGEST = hashlib.sha256(b"acx-integration-dummy-secret").hexdigest()


def generate_secret() -> str:
    return secrets.token_urlsafe(32)


def hash_secret(secret: str) -> str:
    if not isinstance(secret, str) or len(secret) < MIN_SECRET_LENGTH:
        raise ValueError(f"secret must be at least {MIN_SECRET_LENGTH} characters")
    return f"{HASH_SCHEME}${hashlib.sha256(secret.encode('utf-8')).hexdigest()}"


def _digest_of(stored: str) -> str | None:
    scheme, _, digest = stored.partition("$")
    if scheme != HASH_SCHEME or len(digest) != 64:
        return None
    return digest


@dataclass(frozen=True)
class IntegrationClient:
    id: uuid.UUID
    code: str
    enabled: bool
    protocols: frozenset[Protocol]
    secret_hash: str = field(repr=False)
    #: Previous secret, still accepted until `secondary_expires_at` (rotation
    #: overlap). Both are compared on every attempt (constant work).
    secondary_secret_hash: str | None = field(default=None, repr=False)
    secondary_expires_at: datetime | None = None


@dataclass(frozen=True)
class AuthenticatedClient:
    client_id: uuid.UUID
    code: str
    protocols: frozenset[Protocol]


class ClientStore(TypingProtocol):
    def get_by_code(self, code: str) -> IntegrationClient | None: ...


class InMemoryClientStore:
    def __init__(self, clients: list[IntegrationClient] | None = None) -> None:
        self._lock = threading.Lock()
        self._by_code: dict[str, IntegrationClient] = {}
        for client in clients or []:
            self.add(client)

    def add(self, client: IntegrationClient) -> None:
        with self._lock:
            if client.code in self._by_code:
                raise ValueError("duplicate client code")
            self._by_code[client.code] = client

    def replace(self, client: IntegrationClient) -> None:
        with self._lock:
            self._by_code[client.code] = client

    def get_by_code(self, code: str) -> IntegrationClient | None:
        with self._lock:
            return self._by_code.get(code)


class ClientAuthenticator:
    def __init__(self, store: ClientStore | None, *, clock: Callable[[], datetime] | None = None) -> None:
        self._store = store
        self._clock = clock or (lambda: datetime.now(UTC))

    def authenticate(
        self, code: str | None, secret: str | None, *, protocol: Protocol
    ) -> AuthenticatedClient:
        if self._store is None:
            raise AuthenticationFailed("no_client_store_configured")
        if not code or not secret:
            raise AuthenticationFailed("missing_credentials")
        if not CLIENT_CODE_PATTERN.fullmatch(code):
            raise AuthenticationFailed("malformed_client_code")
        if len(secret) > MAX_SECRET_LENGTH:
            raise AuthenticationFailed("secret_too_long")

        presented = hashlib.sha256(secret.encode("utf-8")).hexdigest()
        client = self._store.get_by_code(code)
        expected = _digest_of(client.secret_hash) if client else None
        secondary = None
        if client is not None and client.secondary_secret_hash and client.secondary_expires_at:
            if client.secondary_expires_at > self._clock():
                secondary = _digest_of(client.secondary_secret_hash)

        # Always perform exactly two constant-time comparisons, whatever exists.
        matches_primary = hmac.compare_digest(presented, expected or _DUMMY_DIGEST)
        matches_secondary = hmac.compare_digest(presented, secondary or _DUMMY_DIGEST)
        matches = (matches_primary and expected is not None) or (matches_secondary and secondary is not None)

        if client is None:
            raise AuthenticationFailed("unknown_client")
        if expected is None:
            raise AuthenticationFailed("client_secret_misconfigured")
        if len(secret) < MIN_SECRET_LENGTH or not matches:
            raise AuthenticationFailed("invalid_secret")
        if not client.enabled:
            raise AuthenticationFailed("client_disabled")
        if protocol not in client.protocols:
            raise AuthenticationFailed("protocol_not_permitted")

        return AuthenticatedClient(client_id=client.id, code=client.code, protocols=client.protocols)
